"""Product analytics dashboard: conversion statistics over customer sessions."""


def conversion_rate(events):
    """Return the share of sessions whose ``converted`` value is True."""
    if not events:
        return 0.0
    hits = sum(1 for event in events if event.get("converted") is True)
    return hits / len(events)


def pooled_conversion_rate(groups):
    """Return the conversion rate across all sessions in all groups."""
    events = [event for group in groups.values() for event in group]
    return conversion_rate(events)


def conversions_in_window(daily_counts, days):
    """Sum the last ``days`` entries of daily counts (oldest first)."""
    if days <= 0:
        return 0
    return sum(daily_counts[-days:])


def conversion_rate_by_group(groups):
    """Return each group's conversion rate, with keys in ascending order."""
    return {
        name: conversion_rate(groups[name]) if groups[name] else None
        for name in sorted(groups)
    }


def longest_conversion_streak(daily_counts):
    """Return the longest run of consecutive positive daily counts."""
    best = current = 0
    for count in daily_counts:
        if count > 0:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best

"""Utilities for loading and preparing customer-session data."""


def parse_session_log(lines):
    """Parse session records from comma-separated log lines."""
    sessions = []
    for line_number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")

        id_, day_text, converted_text = fields
        try:
            day = int(day_text)
        except ValueError as error:
            raise ValueError(f"line {line_number}: day must be an integer") from error

        if converted_text == "1":
            converted = True
        elif converted_text == "0":
            converted = False
        elif converted_text == "":
            converted = None
        else:
            raise ValueError(f"line {line_number}: converted must be 1, 0, or empty")

        sessions.append({"id": id_, "day": day, "converted": converted})
    return sessions


def dedupe_sessions(events):
    """Keep each id's last record and sort by day, then id."""
    latest = {}
    for event in events:
        latest[event["id"]] = event
    return sorted(latest.values(), key=lambda event: (event["day"], event["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Count converted sessions on each day in the inclusive day range."""
    if end_day < start_day:
        return []

    counts = [0] * (end_day - start_day + 1)
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event.get("converted") is True:
            counts[day - start_day] += 1
    return counts

